// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _check_unapproved_logging(address someKeep, address requester, bytes32 digest, bytes32 r, bytes32 s, bytes32 pubX, bytes32 pubY, bytes32 txid, uint256 utxoSize, bytes memory outpoint, bytes memory redeemerOutputScript, uint256 requestedFee) internal {
        bool a = c.logCreated(someKeep);
        bool b = c.logRedemptionRequested(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint);
        bool d = c.logGotRedemptionSignature(digest, r, s);
        bool e = c.logRegisteredPubkey(pubX, pubY);
        bool f = c.logSetupFailed();
        bool g = c.logFraudDuringSetup();
        bool h = c.logFunded();
        bool i = c.logCourtesyCalled();
        bool j = c.logStartedLiquidation(true);
        bool k = c.logRedeemed(txid);
        bool l = c.logLiquidated();
        bool m = c.logExitedCourtesyCall();
        assertTrue(!a && !b && !d && !e && !f && !g && !h && !i && !j && !k && !l && !m);
    }

    function testFuzz_check_unapproved_logging(address someKeep, address requester, bytes32 digest, bytes32 r, bytes32 s, bytes32 pubX, bytes32 pubY, bytes32 txid, uint256 utxoSize, bytes memory outpoint, bytes memory redeemerOutputScript, uint256 requestedFee) public {
        vm.assume(someKeep.code.length == 0 && uint160(someKeep) > 0xffff && someKeep != address(this) && someKeep != address(c) && someKeep != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && someKeep != 0x000000000000000000636F6e736F6c652e6c6f67 && someKeep != 0x4e59b44847b379578588920cA78FbF26c0B4956C && someKeep != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(requester.code.length == 0 && uint160(requester) > 0xffff && requester != address(this) && requester != address(c) && requester != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && requester != 0x000000000000000000636F6e736F6c652e6c6f67 && requester != 0x4e59b44847b379578588920cA78FbF26c0B4956C && requester != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _check_unapproved_logging(someKeep, requester, digest, r, s, pubX, pubY, txid, utxoSize, outpoint, redeemerOutputScript, requestedFee);
    }
}
